import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.2cFhd8Ux.js";const u=JSON.parse('{"title":"Week 8 — Legacy Code","description":"","frontmatter":{"source":"weeks/08-legacy-code/README.md"},"headers":[],"relativePath":"weeks/08-legacy-code/index.md","filePath":"weeks/08-legacy-code/index.md"}'),n={name:"weeks/08-legacy-code/index.md"};function s(i,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="week-8--legacy-code" tabindex="-1">Week 8 — Legacy Code <a class="header-anchor" href="#week-8--legacy-code" aria-label="Permalink to &quot;Week 8 — Legacy Code&quot;">​</a></h1><blockquote><p>Before an agent changes code that nobody fully understands, pin down what it does now; then change it in steps small enough that each one can be shown to change nothing.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>Reading and reading response on Canvas · submit the week 7 assignment (the Seminar opens with its quiz) · book your <strong>oral exam 1</strong> slot and practice with the <a href="./../../assessment/oral-exams.html#oral-exam-1-week-8">samples</a> · graduate presentation: post one question (<a href="./../../graduate/paper-presentations.html#questions-from-the-class">how</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz on the week 7 assignment (7 min, 🔴 AI off) · talk: seams, characterization and approval tests, refactoring and migrations with agents, what &quot;behavior unchanged&quot; means, the Cursor study (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-08.html" target="_blank" rel="noreferrer">slides</a>) · reading discussion or a graduate paper · demo: an approval test catches an agent&#39;s &quot;harmless cleanup&quot; · Lab preview</td></tr><tr><td><strong>Lab</strong></td><td><strong>Oral exam 1</strong> runs in this Lab and in office-hour slots (<a href="./../../assessment/oral-exams.html">oral exams</a>). Everyone else: <a href="./lab.html#lab--characterize-and-refactor-the-god-module-75-min">characterize <code>bookingService.js</code> and extract one responsibility</a> in small verified steps. <strong>Checkoff</strong> (during the guided lab this week): characterization tests green before and after one extraction</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--prove-the-refactor-changed-nothing">assignment</a> (finish the extraction; prove behavior unchanged; document the seams) · <strong>M1</strong> and peer evaluation 1</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: the refactor and the test scaffolding (approvals on; the agent never edits a committed characterization test) · 🔴 AI off: the quiz, the oral exam, the reading response, your PR description</td></tr><tr><td><strong>Reading</strong></td><td>He, Miller, Agarwal, Kästner &amp; Vasilescu, <a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">&quot;Does AI-Assisted Coding Deliver?&quot;</a> (MSR 2026)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words on Canvas, 🔴 AI off, before the Seminar (<a href="#reading">prompt</a>)</td></tr><tr><td><strong>Team project</strong></td><td><strong>M1</strong> before the week 9 Seminar: each member&#39;s first PR in the team fork, reviewed by a teammate, CI green, with characterization tests first wherever you touched untested code (<a href="./../../project/milestones.html#m1-first-pr">M1</a>); peer evaluation 1; <a href="./../../project/pr-round.html#before-the-round">PR-round preparation</a></td></tr><tr><td><strong>Graduate track</strong></td><td>Borg et al. or He et al., if scheduled (<a href="./../../graduate/paper-presentations.html#the-papers">papers</a>); your study runs toward interim results (due before the week 12 Seminar)</td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h (your oral exam is in one of them or in office hours) · outside about 6 h (CS [5xxx]: 7.5 h): reading 45 min, exam practice 1 h, assignment 2.5 h, M1 2 h</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Find the <a href="./../../resources/glossary.html#seam">seams</a> in a legacy module, name the ones it lacks, and use one to get the code under test.</li><li>Write <a href="./../../resources/glossary.html#characterization-test">characterization tests</a> and an approval test that pin down what code does now, errors and side effects included, and show that they can fail.</li><li>Say what &quot;behavior unchanged&quot; means for a given refactor: what is observed, through which boundary, and what may change.</li><li>Delegate a refactor to an agent in small steps, and prove each one green with a test run at every commit and a <a href="./../../resources/glossary.html#mutation-score">mutation score</a> over the same code before and after.</li><li>Explain the strangler-fig pattern for migrations, and interpret the evidence on AI adoption and complexity.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Minutes</th><th>What happens</th></tr></thead><tbody><tr><td>Due-date quiz</td><td>7</td><td>On the week 7 assignment (<a href="./../../assessment/quizzes.html">quizzes</a>), 🔴 AI off</td></tr><tr><td>Concept talk</td><td>25</td><td>Code without tests; seams; characterization and approval tests; small steps; the strangler fig; the evidence (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-08.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td>Discussion or paper</td><td>20</td><td>Is lines added a fair measure of velocity? Or a graduate presentation</td></tr><tr><td>Live demo</td><td>10</td><td>An agent tidies <code>roomly</code>&#39;s error handling; every shipped test passes; the approval test doesn&#39;t</td></tr><tr><td>Lab preview</td><td>5</td><td>Oral exams, the checkoff, &quot;don&#39;t edit the tests&quot;</td></tr></tbody></table><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>In the <a href="./lab.html#lab--characterize-and-refactor-the-god-module-75-min">Lab</a> you work in your <code>roomly</code> repository from weeks 5–7. <code>src/bookingService.js</code> is the god module: validation, rules, conflicts, storage, the audit log, email, formatting, check-in and the lobby schedule in one file. You map it with an agent (and verify the map), pin its behavior with characterization and approval tests, then have the agent move one responsibility into its own module, one green commit at a time. The <a href="./lab.html#assignment--prove-the-refactor-changed-nothing">assignment</a> finishes the extraction and proves it changed nothing.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>He, Miller, Agarwal, Kästner &amp; Vasilescu, <a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">&quot;Does AI-Assisted Coding Deliver?&quot;</a></strong> (MSR 2026; free on arXiv). 807 repositories that adopted Cursor, against 1,380 matched controls. Lines added rose 281% in the first month and the gain was gone after about two months, while static-analysis warnings (+29.7%) and complexity (+40.7% in a table, 25.1% in the text) stayed up. Doubling complexity went with 64.5% fewer lines added.</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off): State the main finding with two numbers. Pick one design choice (lines added as velocity, how controls were matched, what counts as complexity) and say how it could make the effect look larger or smaller. How would you cite the 40.7% versus 25.1% discrepancy? End with what persistent complexity means for how you&#39;d use an agent on <code>roomly</code> this week, and one question for the Seminar.</p><p>More: <a href="./../../resources/reading-list.html#week-8--legacy-code">reading list, week 8</a>.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>Legacy code is code without tests</strong> (Michael Feathers): you can&#39;t change it and know what you changed. Agents can produce it in weeks.</li><li><strong>A characterization test records what the code does, not what it should do.</strong> In week 6 that was the flaw of LLM-written oracles, which &quot;capture actual rather than expected behaviour&quot; (<a href="https://arxiv.org/abs/2410.21136" target="_blank" rel="noreferrer">Konstantinou et al.</a>); for a refactor it&#39;s what you want. A pinned bug stays pinned; fixing it is a separate, tested commit.</li><li><strong>An approval test</strong> (golden master) records every output and side effect for many inputs in one file and compares later runs against it. Scrub what changes every run; read the file before you approve it.</li><li><strong>Seams.</strong> <code>roomly</code> has some (<code>setNow</code>, the data folder, <code>findConflicts</code>&#39;s <code>bookings</code> option, the exported <code>outbox</code>) and lacks others (ID generation, the audit file, email).</li><li><strong>&quot;Behavior unchanged&quot; is a contract you choose.</strong> Name the boundary: HTTP responses, exports, files written, emails sent. Identical HTTP responses can still hide a change an in-process caller sees.</li><li><strong>Small steps, every one green,</strong> and the agent never touches the characterization tests: <code>git diff</code> on <code>tests/</code> is the check, not a sentence in the prompt.</li><li><strong>Mutation score is a good refactoring gate:</strong> it helps in regression settings and misleads when code may already be buggy (<a href="https://arxiv.org/abs/2607.22880" target="_blank" rel="noreferrer">Zhao, Zhou &amp; Cohen</a>). Compare the same code: the old file, then the old file plus the new one.</li><li><strong>The strangler fig</strong> migrates by growing new code around the old: route one call at a time, run both and compare (a parallel run), and delete the old path last.</li><li><strong>Two horizons.</strong> Cursor adopters&#39; extra output faded while complexity stayed (<a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">He et al.</a>); developers later evolving AI-assisted code showed no significant difference in time or quality (<a href="https://arxiv.org/abs/2507.00788" target="_blank" rel="noreferrer">Borg et al.</a>). The measure and its horizon decide the answer.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>A characterization test pins a result that breaks a Booking rule. Why keep it, and what happens to it after the refactor?</li><li>Name two seams <code>roomly</code> has and one it lacks. What would the missing one let a test do?</li><li>After moving <code>audit()</code> out, the old file&#39;s mutation score rises and the new file&#39;s is low. Did your tests improve?</li><li>A refactor keeps every HTTP response identical but makes <code>getBooking()</code> throw instead of returning <code>null</code>. Is behavior unchanged? For whom?</li><li>Why is a strangler fig with a parallel run safer than swapping in a rewritten module, and what does it cost?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>No agent quota:</strong> move down the week 8 row of <a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a> and log the switch, or move the code by hand: the characterization tests matter more than who moves it.</li><li><strong>StrykerJS won&#39;t run</strong> (it needs Node 22): report the blocker and use the per-commit test run as evidence (<a href="./../../resources/troubleshooting.html">troubleshooting</a>).</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Borg et al., <a href="https://arxiv.org/abs/2507.00788" target="_blank" rel="noreferrer">&quot;Echoes of AI&quot;</a>: a preregistered two-phase study and a model of method; a <a href="./../../graduate/paper-presentations.html">graduate seminar</a> paper, as is He et al.</li><li>Denisov-Blanch et al., <a href="https://arxiv.org/abs/2608.25241" target="_blank" rel="noreferrer">&quot;A Few Pages of Markdown&quot;</a>: complexity rose 53% in agent-first repositories without a committed configuration file, 27% with one (observational).</li><li>CMU 17-313&#39;s <a href="https://cmu-313.github.io/assignments/P1/2_refactoring/" target="_blank" rel="noreferrer">refactoring assignment</a>, and Feathers&#39; <em>Working Effectively with Legacy Code</em>.</li><li>Previous week: <a href="./../07-test-adequacy/">Measuring Test Adequacy</a>. Next week: <a href="./../09-review-at-scale/">Review at Scale</a>.</li></ul>',23)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
